import * as React from "react";
import { useState } from "react";
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon } from "../../assets/icons";
import "./FilterChip.scss";

export interface FilterChipProps {
  id: string;
  label: string;
  shape?: "semi-rounded" | "rounded";
  type?: "outlined" | "filled";
  disabled?: boolean;
  colour?: "surface" | "primary" | "secondary" | "tertiary"; 
  leadingIcon?: keyof typeof SvgMpaIcon | string;
  trailingIcon?: keyof typeof SvgMpaIcon | string;
  trailingIconSelected?: keyof typeof SvgMpaIcon | string;
  selected?: boolean;
  onClick?: (() => void) | ((id: string, selected: boolean) => void);
  leadingIconColor?: string;
}

const FilterChip: React.FC<FilterChipProps> = ({
  id,
  label = "Label",
  shape = "semi-rounded",
  type = "outlined",
  disabled=false,
  colour = "surface",
  leadingIcon = "MapPin", 
  trailingIcon = "ChevronDown", 
  trailingIconSelected = "Check",
  selected, 
  onClick,
  leadingIconColor="#000"
}) => {
  const [internalSelected, setInternalSelected] = useState(false);
  const [isDragging, setIsDragging] = useState(false);

  const isSelected = selected !== undefined ? selected : internalSelected;

  const handleToggle = () => {
    const newSelected = !selected;

    if(selected === undefined){
      setInternalSelected(newSelected);
    }
    if(onClick) {
      if (onClick.length === 0) {
        (onClick as () => void)();
      } else {
        (onClick as (id: string, selected: boolean) => void)(id, newSelected);
      }
    }
  };

  const iconSize = "16";

  const className = [
    "filter-chip",
    `chip-${shape}`,
    `chip-${type}`,
    disabled ? "disabled" : "",
    `${colour}-chip`, 
    isDragging ? "dragging" : "",
    isSelected ? `selected ${colour}-chip` : "", 
  ]
    .filter(Boolean)
    .join(" ");
  
  return (
    <div id={id}>
      <button
        className={className}
        draggable="true"
        onDragStart={() => setIsDragging(true)}
        onDragEnd={() => setIsDragging(false)}
        onClick={handleToggle}
        disabled={disabled}
        aria-pressed={isSelected}
      >
        <MpaIcon iconName={leadingIcon} size={iconSize} colour={leadingIconColor}/>
        {label}
        {trailingIcon && (          
            <MpaIcon
              iconName={isSelected ? trailingIconSelected : trailingIcon}
              size={iconSize}
            />          
        )}
      </button>
    </div>
  );
};

export default FilterChip;
